css:
/* Benefit columns: a title over a short rule, then one benefit per line with a small marker. */
.bz-section[data-bz-node="bf"]{padding-block:clamp(40px,5vw,72px)}
[data-bz-node="bf"] .bz-block{padding-block:0}
[data-bz-node="bf-head"]{margin-bottom:clamp(24px,3vw,40px)}
[data-bz-node="bf-h"] h2{margin-bottom:var(--space-3)}
[data-bz-node="bf-intro"] p{max-width:46rem;margin:0}
[data-bz-node="bf-grid"]{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:clamp(28px,4vw,56px);align-items:start}
[data-bz-node^="bf-col"]{grid-column:auto;min-width:0;border-top:2px solid var(--ink);padding-top:var(--space-4)}
[data-bz-node^="bf-title"] h3{font:700 1.125rem/1.25 var(--font-heading);text-transform:uppercase;margin:0 0 var(--space-3);color:var(--ink)}
[data-bz-node^="bf-item"]{margin-bottom:8px}
[data-bz-node^="bf-item"] p{position:relative;margin:0;padding-left:18px;font-size:.9375rem;line-height:1.5;color:#3d3c39}
[data-bz-node^="bf-item"] p::before{content:"";position:absolute;left:3px;top:.62em;width:6px;height:6px;border-radius:50%;background:var(--accent)}
[data-bz-node^="bf-item"] p:empty{display:none}
@media (max-width:640px){[data-bz-node="bf-grid"]{grid-template-columns:1fr}}
